<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { uid, type Block } from '../model';
type Row = Record<string, unknown>;
type Widget = { id: string; title: string; sql: string; display: 'table' | 'metric' };
type Dashboard = { id: string; title: string; widgets: Widget[]; pinned?: boolean };
const props = defineProps<{ block: Block; environment: string; initialId?: string; runQuery: (sql: string) => Promise<Row> }>();
function saved(): Dashboard[] {
  try { const data = JSON.parse(props.block.value); if (Array.isArray(data.dashboards)) return data.dashboards.filter((d: Dashboard) => d && typeof d.id === 'string' && Array.isArray(d.widgets)); } catch { /* no saved dashboards */ }
  return [];
}
const dashboards = ref<Dashboard[]>(saved()), selected = ref(dashboards.value.find(d => d.id === props.initialId)?.id || dashboards.value[0]?.id || ''), editing = ref(false), error = ref('');
const dashboard = computed(() => dashboards.value.find(d => d.id === selected.value));
const results = ref<Record<string, Row[]>>({}), errors = ref<Record<string, string>>({}), busy = ref<Record<string, boolean>>({});
watch(dashboards, () => { let data: Record<string, unknown> = {}; try { data = JSON.parse(props.block.value) || {}; } catch { /* new state */ } props.block.value = JSON.stringify({ ...data, dashboards: dashboards.value }); }, { deep: true });
watch([selected, () => props.environment], () => { results.value = {}; errors.value = {}; });
function create() { const d: Dashboard = { id: uid(), title: 'Untitled dashboard', widgets: [] }; dashboards.value.push(d); selected.value = d.id; editing.value = true; }
function addWidget() { dashboard.value?.widgets.push({ id: uid(), title: 'New table', sql: 'SELECT id, name FROM file WHERE ROWNUM <= 20', display: 'table' }); }
function removeWidget(id: string) { if (dashboard.value) dashboard.value.widgets = dashboard.value.widgets.filter(w => w.id !== id); delete results.value[id]; }
function removeDashboard() { dashboards.value = dashboards.value.filter(d => d.id !== selected.value); selected.value = dashboards.value[0]?.id || ''; editing.value = false; }
async function refresh(widget: Widget) {
  if (busy.value[widget.id]) return;
  const environment = props.environment, dashboardId = selected.value;
  busy.value[widget.id] = true; delete errors.value[widget.id];
  try { const value = await props.runQuery(widget.sql); if (environment === props.environment && dashboardId === selected.value) results.value[widget.id] = Array.isArray(value.rows) ? value.rows as Row[] : []; }
  catch (e) { if (environment === props.environment && dashboardId === selected.value) errors.value[widget.id] = e instanceof Error ? e.message : String(e); }
  finally { busy.value[widget.id] = false; }
}
async function refreshAll() { if (!dashboard.value) return; for (const widget of dashboard.value.widgets) await refresh(widget); }
const columns = (rows: Row[]) => Array.from(new Set(rows.flatMap(r => Object.keys(r))));
</script>
<template>
  <div class="dash-workspace">
    <aside class="dash-sidebar"><div class="dash-sidebar-heading"><strong>Dashboards</strong><button class="subtle-button" @click="create">New</button></div><button v-for="d in dashboards" :key="d.id" class="dash-select" :class="{ active: selected === d.id }" @click="selected = d.id; editing = false">{{ d.title || 'Untitled dashboard' }}</button><p v-if="!dashboards.length">Create a dashboard to bring queries together.</p></aside>
    <div class="dash-main" v-if="dashboard"><div class="dash-toolbar"><input v-if="editing" v-model="dashboard.title" aria-label="Dashboard title"/><h2 v-else>{{ dashboard.title || 'Untitled dashboard' }}</h2><button class="subtle-button" @click="refreshAll" :disabled="Object.values(busy).some(Boolean) || !dashboard.widgets.length">Refresh all</button><button class="subtle-button" :aria-label="dashboard.pinned ? 'Unpin dashboard from Home' : 'Pin dashboard to Home'" :aria-pressed="!!dashboard.pinned" @click="dashboard.pinned = !dashboard.pinned">{{ dashboard.pinned ? 'Unpin' : 'Pin to Home' }}</button><button class="subtle-button" @click="editing = !editing">{{ editing ? 'Done' : 'Edit' }}</button><button v-if="editing" class="subtle-button" @click="addWidget">Add widget</button><button v-if="editing" class="subtle-button" @click="removeDashboard">Delete dashboard</button></div>
      <p v-if="error" role="alert">{{ error }}</p><div class="dash-grid"><div v-for="widget in dashboard.widgets" :key="widget.id" class="dash-widget"><div class="dash-widget-head"><input v-if="editing" v-model="widget.title" aria-label="Widget title"/><strong v-else>{{ widget.title }}</strong><button class="subtle-button" :disabled="busy[widget.id]" @click="refresh(widget)">{{ busy[widget.id] ? 'Loading…' : 'Refresh' }}</button><button v-if="editing" class="subtle-button" @click="removeWidget(widget.id)">Remove</button></div><template v-if="editing"><div class="dash-display"><button :class="{ active: widget.display === 'table' }" @click="widget.display = 'table'">Table</button><button :class="{ active: widget.display === 'metric' }" @click="widget.display = 'metric'">Metric</button></div><label>SuiteQL<textarea v-model="widget.sql" aria-label="Widget SuiteQL" rows="4" spellcheck="false"/></label></template><p v-if="errors[widget.id]" class="dash-error" role="alert">{{ errors[widget.id] }}</p><template v-else-if="results[widget.id]"><div v-if="widget.display === 'metric'" class="dash-metric">{{ Object.values(results[widget.id]![0] || {})[0] ?? '—' }}</div><div v-else class="dash-table-scroll"><div v-if="results[widget.id]!.length" class="dash-table" :style="{ minWidth: `${columns(results[widget.id]!).length * 140}px`, gridTemplateColumns: `repeat(${columns(results[widget.id]!).length}, minmax(140px,1fr))` }"><div class="dash-table-head"><span v-for="col in columns(results[widget.id]!)" :key="col">{{ col }}</span></div><div class="dash-table-body"><div v-for="(row, index) in results[widget.id]" :key="index" class="dash-table-row"><span v-for="col in columns(results[widget.id]!)" :key="col">{{ row[col] }}</span></div></div></div><p v-else>No rows returned.</p></div></template><p v-else class="dash-empty">Refresh to load data from this environment.</p></div><p v-if="!dashboard.widgets.length" class="dash-empty">Edit this dashboard and add a widget to display NetSuite data.</p></div></div>
    <div v-else class="dash-empty-main"><strong>Your dashboards</strong><p>Build a view of the NetSuite data you use most.</p><button class="subtle-button" @click="create">Create dashboard</button></div>
  </div>
</template>
<style scoped>
.dash-workspace{display:flex;flex:1;min-height:0}.dash-sidebar{width:180px;flex-shrink:0;padding:12px;border-right:1px solid #dce5e9;overflow:auto}.dash-sidebar-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px}.dash-sidebar p,.dash-empty,.dash-empty-main p{color:#657b89;line-height:1.5}.dash-select{display:block;width:100%;text-align:left;border:0;background:none;color:inherit;padding:9px;border-radius:5px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;cursor:pointer}.dash-select.active{background:#e2edf2;font-weight:600}.dash-main{flex:1;min-width:0;display:flex;flex-direction:column}.dash-toolbar{display:flex;gap:8px;align-items:center;padding:12px 16px;border-bottom:1px solid #dce5e9;flex-wrap:wrap}.dash-toolbar h2{font-size:15px;margin:0;margin-right:auto}.dash-toolbar input,.dash-widget-head input{flex:1;min-width:100px;border:0;border-bottom:1px solid #cbd9df;background:#eef3f5;padding:8px;color:inherit}.dash-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,340px),1fr));gap:12px;align-content:start;padding:16px;overflow:auto}.dash-widget{min-width:0;border:1px solid #dce5e9;background:#fbfcfd;border-radius:6px;padding:14px}.dash-widget-head{display:flex;gap:6px;align-items:center}.dash-widget-head strong{margin-right:auto}.dash-display{display:flex;gap:4px;margin:12px 0 6px}.dash-display button{border:0;padding:6px 10px;color:#657b89;background:#edf3f6}.dash-display button.active{background:#dce9ef;color:#344d5b}.dash-widget label{display:flex;flex-direction:column;gap:6px;color:#657b89}.dash-widget textarea{resize:vertical;min-height:70px;padding:8px;border:1px solid #dce5e9;background:#f0f5f7;color:#344d5b;font:12px/1.5 Consolas,monospace}.dash-metric{font-size:28px;padding:20px 0;color:#344d5b}.dash-table-scroll{overflow-x:auto;overflow-y:hidden;height:240px;margin-top:10px}.dash-table{display:grid;grid-template-rows:auto minmax(0,1fr);height:100%}.dash-table-head,.dash-table-row{display:grid;grid-column:1/-1;grid-template-columns:subgrid}.dash-table-head{color:#657b89;font-weight:600;padding-right:8px;background:#f1f5f7}.dash-table-body{grid-column:1/-1;display:grid;grid-template-columns:subgrid;align-content:start;overflow-y:scroll;scrollbar-gutter:stable}.dash-table-head span,.dash-table-row span{padding:8px;border-bottom:1px solid #e4ebee;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.dash-error{color:#9b3835}.dash-empty-main{padding:24px}.dash-empty-main strong{font-size:15px}@media(max-width:650px){.dash-sidebar{width:120px}.dash-toolbar{gap:4px}}
</style>
